// Illustrative example, Verifiable Intent 0.1 on main (356c296). Specified; live use not shown publicly.
{
  "vct": "mandate.payment.open.1",
  "cnf": { "jwk": { "kty": "EC", "crv": "P-256", "x": "<agent-key-x>", "y": "<agent-key-y>", "kid": "agent-key-1" } },
  "payment_instrument": { "type": "mastercard.srcDigitalCard", "id": "<token-uuid>" },
  "constraints": [
    { "type": "mandate.payment.amount_range", "currency": "USD", "max": 20000 },
    { "type": "mandate.payment.reference", "conditional_transaction_id": "<B64U(SHA-256(checkout_disclosure))>" }
  ]
}

// Illustrative example, Verifiable Intent 0.1 on main (356c296). Specified; live use not shown publicly.
// L3b disclosed mandate (aud: the merchant)
{ "vct": "mandate.checkout.1", "checkout_jwt": "<merchant checkout_jwt>", "checkout_hash": "<B64U(SHA-256(checkout_jwt))>" }
// L3a disclosed mandate (aud: the payment network)
{
  "vct": "mandate.payment.1",
  "payment_instrument": { "type": "mastercard.srcDigitalCard", "id": "<token-uuid>" },
  "payment_amount": { "currency": "USD", "amount": 12999 },
  "payee": { "name": "Example Shop", "website": "https://shop.example.com" },
  "transaction_id": "<same value as checkout_hash>"
}
